    const buffer = fs.readFileSync(0);
    let offset = 0;

    function readInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let sign = 1;
        if (buffer[offset] === 45) { // '-'
            sign = -1;
            offset++;
        }
        let res = 0;
        while (offset < buffer.length && buffer[offset] >= 48 && buffer[offset] <= 57) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res * sign;
    }

    const L = readInt();
    if (L === null) return;
    const C = readInt();

    const A = new Int32Array(L * C);
    for (let i = 0; i < L * C; i++) {
        A[i] = readInt();
    }

    const rows = L - 1;
    const cols = C - 1;

    if (rows <= 0 || cols <= 0) {
        console.log(0);
        return;
    }

    const heights = new Int32Array(cols);
    const stack = new Int32Array(cols + 1);

    let maxArea = 0;

