        const rowOffsetA1 = i * C;
        const rowOffsetA2 = (i + 1) * C;

        for (let j = 0; j < cols; j++) {
            const val1 = A[rowOffsetA1 + j] + A[rowOffsetA2 + j + 1];
            const val2 = A[rowOffsetA1 + j + 1] + A[rowOffsetA2 + j];

            if (val1 <= val2) {
                heights[j]++;
            } else {
                heights[j] = 0;
            }
        }

        let top = -1;
        for (let j = 0; j <= cols; j++) {
            const h = (j === cols) ? 0 : heights[j];
            while (top >= 0 && heights[stack[top]] >= h) {
                const height = heights[stack[top--]];
                const left = (top < 0) ? -1 : stack[top];
                const width = j - left - 1;
                const area = (height + 1) * (width + 1);
                if (area > maxArea) {
                    maxArea = area;
                }
            }
            stack[++top] = j;
        }
    }

    console.log(maxArea);
}

solve();
